import React from 'react';
import { View, Text } from 'react-native';

import { Feather, SimpleLineIcons } from '@expo/vector-icons';
import { styles } from './styles';

export function CustomHeader() {
    return (
        <View style={styles.container}>
            <Text style={styles.title}>FMLRIFAS</Text>
            <View style={styles.containerMenu}>
                <View style={{flex: 1, alignItems: 'center',justifyContent: 'center'}}>
                    <Feather name="shopping-cart" size={25} color="#fff" />
                    <View  style={{ position: 'absolute', backgroundColor:'#FF0000', borderRadius: 30, alignItems: 'center', justifyContent: 'center', padding: 5 }}>
                    <Text style={{ textAlign: 'center', fontSize: 30, color: '#fff', }}>15</Text>
                    </View>
                </View>
                <SimpleLineIcons name="menu" size={25} color="#fff" />
            </View>
        </View>
    );
};
